package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_clone_TriageGen0Test {

    @Test
    public void testCloneBasicProperties() {
        // Setup: Create an element with attributes and text
        Element original = Parser.parseBodyFragment("<div id=\"test\" class=\"foo\">Hello</div>").selection().first();

        // Execution
        Element cloned = original.clone();

        // Verification: Identity
        Assert.assertNotSame("Cloned object should be a different instance", original, cloned);

        // Verification: Tag and Attributes
        Assert.assertEquals("Tag name should match", original.tagName(), cloned.tagName());
        Assert.assertEquals("ID attribute should match", original.id(), cloned.id());
        Assert.assertEquals("Class attribute should match", original.className(), cloned.className());

        // Verification: Content
        Assert.assertEquals("Text content should match", original.text(), cloned.text());
    }

    @Test
    public void testCloneWithChildren() {
        // Setup: Create a nested structure
        Element original = Parser.parseBodyFragment("<ul><li class=\"item\">1</li><li class=\"item\">2</li></ul>").selection().first();

        // Execution
        Element cloned = original.clone();

        // Verification: Structure
        Assert.assertEquals("Number of children should match", original.children().size(), cloned.children().size());
        Assert.assertEquals("Child 0 tag should match", original.child(0).tagName(), cloned.child(0).tagName());
        Assert.assertEquals("Child 0 class should match", original.child(0).className(), cloned.child(0).className());
        Assert.assertEquals("Child 1 text should match", original.child(1).text(), cloned.child(1).text());

        // Verification: Deep copy check (elements should be different instances but same data)
        Assert.assertNotSame("Children should be new instances", original.child(0), cloned.child(0));
    }

    @Test
    public void testCloneWithComplexAttributes() {
        // Setup: Element with various attributes
        Element original = new Element(org.jsoup.parser.Tag.valueOf("span"), "");
        original.attr("data-id", "123");
        original.attr("custom-attr", "value");
        original.attr("class", "my-class");

        // Execution
        Element cloned = original.clone();

        // Verification
        Assert.assertEquals("data-id should match", "123", cloned.attr("data-id"));
        Assert.assertEquals("custom-attr should match", "value", cloned.attr("custom-attr"));
        Assert.assertEquals("class should match", "my-class", cloned.className());
    }

    @Test
    public void testCloneEmptyElement() {
        // Setup: Empty element
        Element original = new Element(org.jsoup.parser.Tag.valueOf("br"), "");

        // Execution
        Element cloned = original.clone();

        // Verification
        Assert.assertEquals("Tag name should match for empty element", "br", cloned.tagName());
        Assert.assertTrue("Cloned element should be empty", cloned.children().isEmpty());
    }
}
